package com.oguzguven.portfolio.contact; import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ContactService{private final ContactRepository repository;public ContactService(ContactRepository repository){this.repository=repository;}@Transactional(readOnly=true)public ContactResponse get(){return ContactResponse.from(repository.findById(1L).orElseThrow());}@Transactional public ContactResponse update(ContactRequest request){var value=repository.findById(1L).orElseGet(()->new Contact(request));value.update(request);return ContactResponse.from(repository.save(value));}}
